// This script is generated by Gemini
using UnityEngine;

public class SpritePulse : MonoBehaviour
{
    [Tooltip("The SpriteRenderer to pulse")]
    public SpriteRenderer spriteRenderer;
    
    [Tooltip("How fast the glow pulses")]
    public float pulseSpeed = 4f;
    
    [Tooltip("The standard color of the sprite")]
    public Color normalColor = Color.white;
    
    [Tooltip("The color it shifts to at the peak of the glow. Lower the Alpha (A) for a fade effect, or change RGB for a color tint.")]
    public Color glowColor = new Color(1f, 1f, 1f, 0.4f); 

    void Start()
    {
        // Automatically grab the SpriteRenderer if it's on the same object
        if (spriteRenderer == null) 
        {
            spriteRenderer = GetComponent<SpriteRenderer>();
        }
    }

    void Update()
    {
        // Only calculate the pulse if a debris sprite is actually being displayed (Level > 0)
        if (spriteRenderer != null && spriteRenderer.sprite != null)
        {
            // Mathf.Sin creates a smooth, repeating wave. We normalize it to stay between 0 and 1.
            float wave = (Mathf.Sin(Time.time * pulseSpeed) + 1f) / 2f;
            
            // Blend smoothly between the normal color and the glow color based on the wave
            spriteRenderer.color = Color.Lerp(normalColor, glowColor, wave);
        }
    }
}